#include "project.h"
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

int node_erase(struct node *node)
{
	const char *newline = strstr(node->source.data, "\r\n") ? "\r\n" : "\n";
	return text_append(&node->output, node->source.data, node->begin) &&
		text_append(&node->output, newline, strlen(newline)) &&
		text_append(&node->output, node->source.data + node->end,
			    node->source.length - node->end);
}

static int model_name(struct text *output, const char *name)
{
	if (!text_append(output, "MSN_", 4))
		return 0;
	while (*name) {
		char upper = (char)toupper((unsigned char)*name++);
		if (!text_append(output, &upper, 1))
			return 0;
	}
	return 1;
}

int node_generate(struct em_project *project, size_t index)
{
	struct node *target = project->nodes + index;
	struct text code = { 0 };
	size_t n = project->count + 1, i, j, count;
	size_t *order = malloc(n * sizeof(*order));
	size_t *bases = malloc(n * sizeof(*bases));
	size_t *position = calloc(n, sizeof(*position));
	size_t *seats = calloc(n, sizeof(*seats));
	int ok = 0;
#define EMIT(...) do { if (!text_printf(&code, __VA_ARGS__)) goto done; } while (0)
	if (!order || !bases || !position || !seats)
		goto done;
	count = graph_order(project, index, order);
	if (!count)
		goto done;
	for (i = 0; i < count; i++)
		position[order[i]] = i;
	seats[index] = 1;
	/* Longest active chain of downward delegation, including the external
	 * caller. Repeated relaxation also handles shared bases visited early. */
	for (i = 0; i < count; i++) {
		int changed = 0;
		for (j = 0; j < count; j++) {
			size_t id = order[j], k;
			if (id == project->count || !seats[id])
				continue;
			struct node *node = project->nodes + id;
			for (k = 0; k < node->direct_count; k++) {
				size_t base = node->direct[k];
				if (seats[base] < seats[id] + 1) {
					seats[base] = seats[id] + 1;
					changed = 1;
				}
			}
		}
		if (!changed)
			break;
	}
	EMIT("\n/* Generated by OpenOICC; edit business code outside this region. */\n#include \"openoicc/construct.h\"\n");
	EMIT("int crt_%s(uint64_t *object_id, unsigned int input_capacity,\n\tunsigned int output_capacity, int caller_capacity,\n\tstruct object **object_out, unsigned char *exotic_memory)\n{\n", target->name);
	for (i = 0; i < count; i++) {
		size_t id = order[i];
		const char *name = id == project->count ? "neoioic" : project->nodes[id].name;
		EMIT("\textern void tog_%s(struct object *);\n", name);
		EMIT("\t_Static_assert(");
		if (!model_name(&code, name))
			goto done;
		EMIT(" > 0 &&\n\t\t");
		if (!model_name(&code, name))
			goto done;
		EMIT(" <= USHRT_MAX,\n\t\t\"model id out of range\");\n");
		if (id == project->count)
			continue;
		struct node *node = project->nodes + id;
		EMIT("\tstatic const unsigned short direct_%zu[] = {", i);
		for (j = 0; j < node->direct_count; j++)
			EMIT("%s%zu", j ? ", " : " ", position[node->direct[j]]);
		EMIT(" };\n\tstatic const unsigned short bases_%zu[] = {", i);
		size_t base_count = graph_order(project, id, bases);
		if (!base_count)
			goto done;
		for (j = 1; j < base_count; j++)
			EMIT("%s%zu", j > 1 ? ", " : " ", position[bases[j]]);
		EMIT(" };\n");
	}
	EMIT("\tconst struct openoicc_layout layout[] = {\n");
	for (i = 0; i < count; i++) {
		size_t id = order[i], base_count = 0;
		int root = id == project->count;
		struct node *node = root ? NULL : project->nodes + id;
		const char *name = root ? "neoioic" : node->name;
		EMIT("\t\t{ ");
		if (!model_name(&code, name))
			goto done;
		EMIT(", tog_%s,\n\t\t  ", name);
		if (root || node->has_members)
			EMIT("NEOIOIC_ALIGNED_SIZE(struct em_%s),\n\t\t  _Alignof(struct em_%s), ", name, name);
		else
			EMIT("0, 1, ");
		EMIT("%zu, ", seats[id]);
		if (root) {
			EMIT("NULL, 0, NULL, 0 },\n");
			continue;
		}
		for (j = 0; j < n; j++)
			base_count += project->reach[id * n + j] != 0;
		EMIT("direct_%zu, %zu, bases_%zu, %zu },\n", i, node->direct_count, i, base_count);
	}
	EMIT("\t};\n\treturn openoicc_construct(layout, sizeof(layout) / sizeof(layout[0]),\n\t\tobject_id, input_capacity, output_capacity, caller_capacity,\n\t\tobject_out, exotic_memory);\n}\n");
	/* Keep the source newline convention and all bytes outside the region. */
	if (!text_append(&target->output, target->source.data, target->begin))
		goto done;
	int crlf = strstr(target->source.data, "\r\n") != NULL;
	for (i = 0; i < code.length; i++) {
		if (crlf && code.data[i] == '\n' && !text_append(&target->output, "\r", 1))
			goto done;
		if (!text_append(&target->output, code.data + i, 1))
			goto done;
	}
	ok = text_append(&target->output, target->source.data + target->end,
			 target->source.length - target->end);
done:
	free(order);
	free(bases);
	free(position);
	free(seats);
	free(code.data);
	return ok;
#undef EMIT
}
